// ===== DM AUTO-RESPONDER =====
// Handles incoming DMs with smart responses

const staticData = $getWorkflowStaticData('global');
const kb = staticData.knowledgeBase || {};
const niche = staticData.niche || 'your niche';

// DM trigger keywords and responses
const dmTriggers = {
  // Product link requests
  productLink: {
    keywords: ['link', 'product', 'buy', 'purchase', 'where', 'how much', 'price', 'cost', 'order', 'shop'],
    response: `Hey! 👋 Thanks for reaching out!

Here's the link you asked for: [PRODUCT_LINK]

Let me know if you have any questions! 💬`,
    followUp: `Hey! Just checking in — did you get a chance to check out the link? Let me know if you need anything! 🙌`,
    followUpDelay: '24h'
  },

  // Collaboration requests
  collab: {
    keywords: ['collab', 'collaborate', 'work together', 'partner', 'partnership', 'feature', 'shoutout'],
    response: `Hey! Thanks for reaching out about collaboration! 🤝

I'm always open to working with like-minded creators in the ${niche} space.

Can you tell me more about what you have in mind?

• What's your account about?
• What type of collaboration are you thinking?
• What's your audience size?

Looking forward to hearing from you! 🚀`,
    priority: 'high'
  },

  // Questions about niche
  question: {
    keywords: ['how', 'what', 'why', 'when', 'where', 'advice', 'tip', 'help', 'guide', 'recommend'],
    response: `Hey! Great question! 💡

I actually have a lot of content about this on my page. Check out my recent carousels for detailed tips!

For personalized advice, I offer 1-on-1 coaching sessions. DM me

 for details! 🎯`,
    priority: 'medium'
  },

  // Coaching/service inquiries
  coaching: {
    keywords: ['coaching', 'mentor', 'mentorship', 'learn', 'teach', 'train', 'course', 'program'],
    response: `Hey! So glad you're interested in leveling up! 🚀

Here's what I offer:

📚 1-on-1 Coaching: $X/session
🎓 Group Program: $X/month
📋 Self-Paced Course: $X one-time

DM me

 to get started or ask me anything! 💪`,
    priority: 'high'
  },

  // Positive feedback
  love: {
    keywords: ['love', 'amazing', 'great', 'awesome', 'fire', 'best', 'inspire', 'helpful', 'changed', 'thank'],
    response: `Thank you SO much! 🙏❤️

Messages like this keep me going! Really glad my content is helping.

Keep crushing it! 🔥`,
    priority: 'low'
  },

  // Join community
  community: {
    keywords: ['group', 'community', 'join', 'discord', 'telegram', 'member', 'membership'],
    response: `Hey! 👋

I'd love to have you in the community! 🎉

Here's how to join:
🔗 [COMMUNITY_LINK]

Inside you'll get:
✅ Exclusive content
✅ Direct access to me
✅ Community support
✅ Weekly Q&A sessions

See you inside! 🚀`,
    priority: 'medium'
  }
};

// Comment-triggered DMs (when someone comments specific keywords)
const commentDmTriggers = {
  'link': `Hey {{username}}! 👋

Thanks for your interest! Here's the link:
🔗 [PRODUCT_LINK]

Let me know if you have questions! 💬`,

  'info': `Hey {{username}}! 🙌

Here's all the info you need:
📋 [INFO_LINK]

DM me if you want to know more!`,

  'guide': `Hey {{username}}! 📚

Here's the free guide I mentioned:
📥 [GUIDE_LINK]

Hope it helps! Let me know what you think! 💡`,

  'start': `Hey {{username}}! 🚀

Ready to get started? Here's your next step:
👉 [NEXT_STEP_LINK]

I'm here if you need help! 💪`
};

// Store DM templates
staticData.dmTriggers = dmTriggers;
staticData.commentDmTriggers = commentDmTriggers;

return [{
  json: {
    dmTriggers,
    commentDmTriggers,
    chatId: staticData.chatId
  }
}];

// ===== ENGAGEMENT BOT =====
// Auto-engages with target audience

const staticData = $getWorkflowStaticData('global');
const kb = staticData.knowledgeBase || {};
const niche = staticData.niche || 'general';

// Engagement targets
const engagementTargets = {
  // Like comments on our posts
  ownPosts: {
    action: 'like_comments',
    frequency: 'every 30 min',
    maxPerBatch: 20,
    priority: 'high'
  },

  // Engage with competitor followers
  competitorFollowers: {
    action: 'like_and_comment',
    targets: kb.competitors?.slice(0, 5) || [],
    commentTemplates: [
      'Great post! 🔥',
      'Love this! ❤️',
      'So true! 💯',
      'Amazing content! 🙌',
      'This is fire! 🔥'
    ],
    maxPerHour: 15,
    priority: 'medium'
  },

  // Engage with niche hashtags
  hashtagEngagement: {
    action: 'like_recent',
    hashtags: kb.topHashtags?.slice(0, 5) || [niche],
    maxPerHashtag: 10,
    priority: 'low'
  },

  // Follow/unfollow strategy
  followStrategy: {
    action: 'follow_engaged',
    criteria: [
      'Liked our post',
      'Commented on competitor posts',
      'Active in niche hashtags'
    ],
    maxFollowsPerDay: 20,
    unfollowAfterDays: 3,
    priority: 'medium'
  }
};

// Engagement schedule
const engagementSchedule = [
  { time: '08:00', action: 'Like recent comments on own posts' },
  { time: '09:00', action: 'Engage with competitor followers' },
  { time: '10:00', action: 'Like posts in niche hashtags' },
  { time: '12:00', action: 'Reply to DMs and comments' },
  { time: '14:00', action: 'Engage with competitor followers' },
  { time: '16:00', action: 'Like posts in niche hashtags' },
  { time: '18:00', action: 'Reply to DMs and comments' },
  { time: '20:00', action: 'Engage with competitor followers' },
  { time: '22:00', action: 'Like recent comments on own posts' }
];

staticData.engagementTargets = engagementTargets;
staticData.engagementSchedule = engagementSchedule;

return [{
  json: {
    engagementTargets,
    engagementSchedule,
    chatId: staticData.chatId
  }
}];
